def ship_within_days(weights, days):
    def days_needed(capacity):
        used, load = 1, 0
        for weight in weights:
            if load + weight > capacity:       # it does not fit today: start a new day
                used, load = used + 1, 0
            load += weight
        return used

    lo, hi = max(weights), sum(weights)        # at least the heaviest package, at most everything in one day
    while lo < hi:
        mid = (lo + hi) // 2
        if days_needed(mid) <= days:
            hi = mid                           # mid is enough; perhaps something smaller is too
        else:
            lo = mid + 1
    return lo
